SELECT COUNT(*) FROM CONTACT_TBL c
WHERE NVL(c.DELETE_YN, 'N') = 'N'
  AND c.USER_NO = #{userNo}

SELECT c.CONTACT_NO, c.USER_NO, u.USER_ID, u.USER_NICKNAME, c.CONTACT_TITLE, c.CONTACT_CONTENT, c.CATEGORY, c.STATUS, c.ANSWER_CONTENT, c.ANSWER_AT, c.CREATED_AT, c.DELETE_YN FROM CONTACT_TBL c JOIN USER_TBL u ON c.USER_NO = u.USER_NO
NVL(c.DELETE_YN, 'N') = 'N'
AND c.STATUS = #{status}
AND c.CATEGORY = #{category}
ORDER BY c.CONTACT_NO DESC

SELECT COUNT(*) FROM CONTACT_TBL c

    NVL(c.DELETE_YN, 'N') = 'N'

        AND c.STATUS = #{status}


        AND c.CATEGORY = #{category}

